head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue + "\n");
};

scwin.onpageload = function () {
};

// [재현 버튼] 유효 ID(input2) 설정 -> 존재하지 않는 ID(none) 설정 순서로 호출하며 getNextTabID 로 저장값 확인
scwin.btn_reproduce_onclick = function () {
    // 1) 유효 ID 설정
    target1.setNextTabID('input2');
    scwin.setReturnValue("[1] setNextTabID('input2') [유효 ID] -> getNextTabID : " + target1.getNextTabID());

    // 2) 존재하지 않는 ID 설정
    target1.setNextTabID('none');
    scwin.setReturnValue("[2] setNextTabID('none') [존재하지 않는 ID] -> getNextTabID : " + target1.getNextTabID());

    // 결과 안내
    scwin.setReturnValue("=> 6월정기 : none 은 존재하지 않으므로 미적용, [1]의 mf_input2 유지 (기대)");
    scwin.setReturnValue("=> 7월정기 : none 을 그대로 저장하여 mf_input2 를 덮어씀 (결함)");
};
